// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Which Google Calendar to use. 'primary' = your main calendar
    calendar_id: "primary",
    // Your time zone, e.g. America/New_York, America/Chicago, America/Los_Angeles
    timezone: "America/New_York",
    // Earliest start time for a call (24-hour clock)
    business_hours_start: "09:00",
    // Calls must end by this time (24-hour clock)
    business_hours_end: "17:00",
    // Days you take calls
    working_days: "Mon,Tue,Wed,Thu,Fri",
    // Length of a strategy call in minutes
    call_minutes: 30,
    // Don't offer times sooner than this many hours from now
    min_notice_hours: 2,
    // How many days ahead to look for openings
    days_to_search: 14,
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
let args = toolCall.function?.arguments ?? toolCall.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const cfg = $('Config').first().json;
const now = DateTime.now().setZone(cfg.timezone);
let from = now.startOf('day');
if (args.requested_date) {
  const d = DateTime.fromISO(String(args.requested_date), { zone: cfg.timezone });
  if (d.isValid && d >= from) from = d.startOf('day');
}
const to = from.plus({ days: Number(cfg.days_to_search) || 14 }).endOf('day');
return [{
  json: {
    tool_call_id: toolCallId,
    requested_date: args.requested_date || '',
    duration_minutes: Number(args.duration_minutes) || Number(cfg.call_minutes) || 30,
    time_min: from.toISO(),
    time_max: to.toISO(),
  },
}];

const cfg = $('Config').first().json;
const req = $('Parse Tool Call').first().json;
const fb = $input.first().json;
const calId = cfg.calendar_id;
const cal = fb.calendars?.[calId] ?? Object.values(fb.calendars ?? {})[0];
const calendarOk = Boolean(cal) && !fb.error && !(cal.errors?.length);
const busy = (cal?.busy ?? []).map((b) => [DateTime.fromISO(b.start), DateTime.fromISO(b.end)]);
const overlaps = (s, e) => busy.some(([bs, be]) => s < be && e > bs);

const DAYS = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7 };
const workDays = String(cfg.working_days).toLowerCase().split(/[\s,]+/).map((d) => DAYS[d.slice(0, 3)]).filter(Boolean);
const [sh, sm] = String(cfg.business_hours_start).split(':').map(Number);
const [eh, em] = String(cfg.business_hours_end).split(':').map(Number);
const minutes = req.duration_minutes;
const earliest = DateTime.now().setZone(cfg.timezone).plus({ hours: Number(cfg.min_notice_hours) || 0 });

const found = [];
let day = DateTime.fromISO(req.time_min, { zone: cfg.timezone });
const last = DateTime.fromISO(req.time_max, { zone: cfg.timezone });
while (calendarOk && found.length < 2 && day <= last) {
  if (workDays.includes(day.weekday)) {
    let t = day.set({ hour: sh, minute: sm || 0, second: 0, millisecond: 0 });
    const close = day.set({ hour: eh, minute: em || 0, second: 0, millisecond: 0 });
    while (found.length < 2 && t.plus({ minutes }) <= close) {
      const end = t.plus({ minutes });
      // Offer the two options at least an hour apart so the caller gets a real choice.
      const spaced = !found.length || t >= found[found.length - 1].plus({ minutes: 60 }) || !t.hasSame(found[0], 'day');
      if (t >= earliest && !overlaps(t, end) && spaced) found.push(t);
      t = t.plus({ minutes: 30 });
    }
  }
  day = day.plus({ days: 1 }).startOf('day');
}

let result;
if (!calendarOk) {
  result = "The calendar couldn't be checked right now. Tell the caller the team will call today to set a time.";
} else if (!found.length) {
  result = 'No openings in the next two weeks. Tell the caller the team will call to find a time that works.';
} else {
  const spoken = found.map((t, i) =>
    `Option ${i + 1}: ${t.toFormat("cccc, LLLL d 'at' h:mm a")} (start_time ${t.toISO()})`).join('. ');
  result = `Open times (${cfg.timezone}): ${spoken}. Offer these in words. ` +
    'If the caller picks one, call bookStrategyCall with that start_time.';
}
return [{ json: { tool_call_id: req.tool_call_id, result } }];
